sys_script_include.script:
var ManageUsersHandler = Class.create();
ManageUsersHandler.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    MANAGERS_GROUP_SYS_ID: '69cf0a56d84053107f44360b568500cf',
    APPROVER_USER_ROLE_SYS_ID: 'debab85bff02110053ccffffffffffb6',

    getGroupMembers: function() {
        var members = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group', this.MANAGERS_GROUP_SYS_ID);
        gr.query();

        while (gr.next()) {
            members.push({
                sys_id: gr.user.toString(),
                name: gr.user.getDisplayValue(),
                email: gr.user.email.toString(),
                title: gr.user.title.toString()
            });
        }

        return JSON.stringify(members);
    },

    searchUsers: function() {
        var query = this.getParameter('sysparm_query');
        if (!query) {
            return JSON.stringify([]);
        }

        // Get users already in the group so we can exclude them
        var existingUsers = {};
        var memberGr = new GlideRecord('sys_user_grmember');
        memberGr.addQuery('group', this.MANAGERS_GROUP_SYS_ID);
        memberGr.query();
        while (memberGr.next()) {
            existingUsers[memberGr.user.toString()] = true;
        }

        var users = [];
        var gr = new GlideRecord('sys_user');
        gr.addActiveQuery();
        var qc = gr.addQuery('name', 'CONTAINS', query);
        qc.addOrCondition('email', 'CONTAINS', query);
        gr.setLimit(20);
        gr.query();

        while (gr.next()) {
            var userSysId = gr.getUniqueValue();
            if (!existingUsers[userSysId]) {
                users.push({
                    sys_id: userSysId,
                    name: gr.getDisplayValue('name'),
                    email: gr.getValue('email'),
                    title: gr.getValue('title')
                });
            }
        }

        return JSON.stringify(users);
    },

    addUserToGroup: function() {
        var userSysId = this.getParameter('sysparm_user_sys_id');

        if (!gs.hasRole('x_274351_finance_0.administrator') && !gs.hasRole('admin')) {
            return JSON.stringify({ success: false, message: 'Insufficient permissions. You must have the administrator or admin role.' });
        }

        if (!userSysId) {
            return JSON.stringify({ success: false, message: 'No user sys_id provided.' });
        }

        // Check if user is already in the group
        var existingMember = new GlideRecord('sys_user_grmember');
        existingMember.addQuery('group', this.MANAGERS_GROUP_SYS_ID);
        existingMember.addQuery('user', userSysId);
        existingMember.query();
        if (existingMember.next()) {
            return JSON.stringify({ success: false, message: 'User is already a member of the FinanceMe2.0 Managers group.' });
        }

        // Add user to the group
        var memberGr = new GlideRecord('sys_user_grmember');
        memberGr.initialize();
        memberGr.setValue('group', this.MANAGERS_GROUP_SYS_ID);
        memberGr.setValue('user', userSysId);
        var memberSysId = memberGr.insert();

        if (!memberSysId) {
            return JSON.stringify({ success: false, message: 'Failed to add user to the group.' });
        }

        // Assign approver_user role if not already assigned
        var existingRole = new GlideRecord('sys_user_has_role');
        existingRole.addQuery('user', userSysId);
        existingRole.addQuery('role', this.APPROVER_USER_ROLE_SYS_ID);
        existingRole.query();

        if (!existingRole.next()) {
            var roleGr = new GlideRecord('sys_user_has_role');
            roleGr.initialize();
            roleGr.setValue('user', userSysId);
            roleGr.setValue('role', this.APPROVER_USER_ROLE_SYS_ID);
            roleGr.insert();
        }

        return JSON.stringify({ success: true, message: 'User added to the FinanceMe2.0 Managers group and assigned approver_user role.' });
    },

    removeUserFromGroup: function() {
        var userSysId = this.getParameter('sysparm_user_sys_id');

        if (!gs.hasRole('x_274351_finance_0.administrator') && !gs.hasRole('admin')) {
            return JSON.stringify({ success: false, message: 'Insufficient permissions. You must have the administrator or admin role.' });
        }

        if (!userSysId) {
            return JSON.stringify({ success: false, message: 'No user sys_id provided.' });
        }

        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group', this.MANAGERS_GROUP_SYS_ID);
        gr.addQuery('user', userSysId);
        gr.query();

        if (!gr.next()) {
            return JSON.stringify({ success: false, message: 'User is not a member of the FinanceMe2.0 Managers group.' });
        }

        gr.deleteRecord();

        return JSON.stringify({ success: true, message: 'User removed from the FinanceMe2.0 Managers group.' });
    },

    type: 'ManageUsersHandler'
});
